Question:
小红希望你构造一个3阶行列式，满足每个元素的绝对值不小于1，且行列式的值等于x。你能帮帮她吗？


Description:
题目：小红的行列式构造

小红希望你构造一个3阶行列式，满足每个元素的绝对值不小于1，且行列式的值等于x。你能帮帮她吗？


Student Program:
#include<bits/stdc++.h>
void solve(int x) {
    int a = 1, b = -1, c = 2, d = 1;
    int e = (x + 1) / 3;
    if (std::abs(e) < 1)
        if (x % 3 == 0) e = (x > 0) ? (x / 3 + 1) : (x / 3 - 1);
        else e = (x > 0) ? (x / 3 + (x % 3 > 0)) : (x / 3 - (x % -3 < 0));
    std::cout << a << " " << 1 << " " << b << std::endl;
    std::cout << 1 << " " << c << " " << 1 << std::endl;
    std::cout << d << " " << 1 << " " << e << std::endl;
}
int main() {
    int x;
    std::cin >> x;
    solve(x);
    return 0;

}


