	std::cin >> n >> m;
	for(int i = 1; i <= n; ++ i) {
		std::string s; std::cin >> s;
		s = " " + s;
		for(int j = 1; j <= m; ++ j) a[i][j] = s[j] - '0';
	}
	for(int i = 1; i <= n; ++ i) {
		for(int j = 1; j <= m; ++ j) {
			if(a[i][j] && vis[i][j] == 0) {
				bfs(i , j);
			}
		}
	}
	std::cout << Min << '\n';
}

